/* aesthetic crumbs v2.17.0 — generated by scripts/build-registry.mjs. */
@import './aesthetic.base.css';

:root {
  --ae-ink-muted: #737373;
  --ae-ink-muted-dark: #8f8f8f;
  --ae-w-medium: 550;
}

@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-ae-mode='light']) {
    --ae-ink-muted: var(--ae-ink-muted-dark);
  }
}

.light,
[data-ae-mode='light'] {
  color-scheme: light;
}

.dark,
[data-ae-mode='dark'] {
  color-scheme: dark;
  --ae-ink-muted: var(--ae-ink-muted-dark);
}

.ae-crumbs {
font-size: 13px;
  color: var(--ae-ink-muted);
}

.ae-crumbs ol {
list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0.6em;
}

.ae-crumbs li {
display: flex;
  gap: 0.6em;
}

.ae-crumbs li + li::before {
content: '/';
  color: var(--ae-ink-faint);
}

.ae-crumbs a {
color: var(--ae-ink-muted);
  text-decoration: none;
}

.ae-crumbs a:hover {
color: var(--ae-ink);
}

.ae-crumbs [aria-current] {
color: var(--ae-ink);
  font-weight: var(--ae-w-medium);
}
